static void tty_pty_partial_feeder(void *arg) {
  static char buf[1<<13];
  ssize_t n;
  ssize_t r;
  int fd;
  int i;

  fd = *(int *)arg;
  memset(buf, 'x', sizeof(buf));
  for (i = 0; i < 8; i++) {
    for (n = 0; n < (int) sizeof(buf); n += r) {
      do
        r = write(fd, &buf[n], sizeof(buf) - n);
      while (r == -1 && errno == EINTR);
      ASSERT_GT(r, 0);
    }
  }
  ASSERT_OK(close(fd));
}
