  uv_fs_req_cleanup(&close_req);

  r = uv_fs_open(NULL, &open_req1, "test_file",
                 UV_FS_O_RDWR | UV_FS_O_APPEND | add_flags, 0, NULL);
  ASSERT_GE(r, 0);
  ASSERT_GE(open_req1.result, 0);
