def _determine_setters(frozen: bool, slots: bool, base_attr_map: dict[str, type]):
    if frozen is True:
        if slots is True:
            return ((), _setattr, _setattr_with_converter)

        def fmt_setter(attr_name: str, value_var: str, has_on_setattr: bool) -> str:
            if _is_slot_attr(attr_name, base_attr_map):
                return _setattr(attr_name, value_var, has_on_setattr)
            return f"_inst_dict['{attr_name}'] = {value_var}"

        def fmt_setter_with_converter(attr_name: str, value_var: str, has_on_setattr: bool, converter: Converter) -> str:
